            BlockState::Thinking { text, signature } => self.keep_block(
                index,
                "thinking",
                ThinkingBlock::Thinking {
                    thinking: text,
                    signature,
                },
                out,
            ),
            BlockState::RedactedThinking { data } => self.keep_block(
                index,
                "redacted_thinking",
                ThinkingBlock::RedactedThinking { data },
                out,
            ),
            BlockState::Text { bytes } => self.position(
                AnthropicData::Text {
                    index,
                    bytes: Some(bytes),
                }
                .into_event(None),
                out,
            ),
            BlockState::ToolUse {
                call_id,
                name_emitted,
                ..
